BEGIN;
INSERT INTO Customers (FirstName, LastName, Email, Phone)
SELECT trim(@first_name), trim(@last_name), trim(@email), nullif(trim(@phone), '')
WHERE NOT EXISTS (SELECT 1 FROM Customers WHERE lower(Email) = lower(trim(@email)));
INSERT INTO Orders (CustomerId, OrderType, Notes)
VALUES (
    (SELECT CustomerId FROM Customers WHERE lower(Email) = lower(trim(@email))),
    @order_type,
    nullif(trim(@notes), ''));
INSERT INTO OrderItems (OrderId, PizzaId, PizzaSizeId, Quantity, UnitPricePence)
VALUES (
    last_insert_rowid(),
    (SELECT PizzaId FROM Pizzas WHERE Name = @pizza),
    (SELECT PizzaSizeId FROM PizzaSizes WHERE Name = @size),
    @quantity,
    (SELECT p.BasePricePence + s.PriceAdjustmentPence FROM Pizzas p, PizzaSizes s
     WHERE p.Name = @pizza AND s.Name = @size));
COMMIT;
